query_jcoql:
GET COLLECTION biologici;
SAVE AS temp_bio@jcoql_test;
GET COLLECTION discounted;
SAVE AS temp_discounted@jcoql_test;
MERGE COLLECTIONS temp_bio@jcoql_test, temp_discounted@jcoql_test REMOVE DUPLICATES;

GET COLLECTION orders;
JOIN OF COLLECTIONS orders@jcoql_test AS o, users@jcoql_test AS u
CASE WHERE .o.user_id = .u._id;

