GET COLLECTION biologici;
FILTER CASE WHERE .organic = TRUE;
SAVE AS sottoinsieme1@jcoql_test;
GET COLLECTION scontati;
FILTER CASE WHERE .discount > 0;
SAVE AS sottoinsieme2@jcoql_test;
MERGE COLLECTIONS sottoinsieme1@jcoql_test, sottoinsieme2@jcoql_test;

GET COLLECTION products;
EXPAND UNPACK TRUE ARRAY .reviews TO .elemento;
FILTER CASE WHERE .elemento.item.rating > 4;

GET COLLECTION products;
EXPAND UNPACK TRUE ARRAY .reviews TO .review;
FILTER CASE WHERE .review.item.rating = 5;

GET COLLECTION products;
EXPAND UNPACK TRUE ARRAY .reviews TO .elemento;
FILTER CASE WHERE .elemento.item.rating < 3;

GET COLLECTION products;
FILTER CASE WHERE .organic = TRUE;
EXPAND UNPACK TRUE ARRAY .reviews TO .elemento;
