GET COLLECTION products;
FILTER CASE WHERE .organic = TRUE;
GROUP PARTITION TRUE BY .category INTO .prodotti_bio_per_categoria;

GET COLLECTION products;
GROUP PARTITION .organic = TRUE BY .organic INTO .biologici
PARTITION .organic = FALSE BY .organic INTO .non_biologici;

GET COLLECTION products;
FILTER CASE WHERE .rating >= 4.0;
SAVE AS sottoinsieme1@jcoql_test;
GET COLLECTION products;
FILTER CASE WHERE .discount > 30;
